    result = evaluate_seal_requirement_check(
        make_check(commodity="produce", weight_lb=Decimal("10000"), equipment_type="reefer")
    )
    assert result.required is True
    assert result.reason_code == "produce_food_safety"


def test_produce_just_below_threshold_does_not_require_seal():
    result = evaluate_seal_requirement_check(
        make_check(commodity="produce", weight_lb=Decimal("9999"), equipment_type="reefer")
    )
    assert result.required is False
    assert result.reason_code == "produce_below_threshold"


